//! 繁 → 簡 conversion for display only.
//!
//! The table lives outside the code (data/shared/t2s.tsv), generated by
//! tools/build_t2s.py from OpenCC plus a few curated 異體字. Two kinds of rule,
//! both of the form source<TAB>target:
//!
//! * one source character → one target character;
//! * a phrase (up to eight characters) → a phrase. A phrase whose target equals
//!   its source is an identity rule: it exists to protect a word from the
//!   character rules (乾隆 must not become 干隆).
//!
//! Conversion is left-to-right longest match at every character position:
//! phrase rules win over character rules, and a character with no rule is
//! copied verbatim. Display only — the corpus is never rewritten on disk.

use std::collections::HashMap;
use std::fs;
use std::io;
use std::path::Path;

/// Longest source the table is allowed to carry, in characters.
pub const MAX_SOURCE_CHARS: usize = 8;

/// Parsed 繁 → 簡 rules. Empty means "no table": conversion is a copy.
#[derive(Debug, Clone, Default)]
pub struct Variants {
    /// One-character rules, keyed by source character.
    chars: HashMap<char, char>,
    /// Phrase rules grouped by source length in characters.
    phrases: HashMap<usize, HashMap<String, String>>,
    /// The lengths that actually occur, longest first, so no window is tried
    /// that cannot possibly match.
    lengths: Vec<usize>,
    /// Total phrase rules, for the startup line (see rule_counts).
    phrase_count: usize,
}

impl Variants {
    /// Read the table from disk. The only failure is I/O; rule syntax that does
    /// not parse is skipped rather than fatal (a comment-only file is empty).
    pub fn load(path: &Path) -> io::Result<Variants> {
        let text = fs::read_to_string(path)?;
        Ok(Variants::parse(&text))
    }

    /// Parse the tab-separated table. Lines starting with # and blank lines are
    /// comments; a line without a tab is ignored.
    pub fn parse(text: &str) -> Variants {
        let mut variants = Variants::default();
        for line in text.lines() {
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let Some((source, target)) = line.split_once('\t') else {
                continue;
            };
            if source.is_empty() || target.is_empty() {
                continue;
            }
            let source_len = source.chars().count();
            let target_len = target.chars().count();
            if source_len == 1 && target_len == 1 {
                let from = source.chars().next().expect("one character");
                let to = target.chars().next().expect("one character");
                variants.chars.insert(from, to);
                continue;
            }
            // Anything a single character cannot carry (a phrase, or a rule that
            // changes the character count) is matched as a window of its own
            // length. The real table only carries 2–8 character phrases.
            if source_len > MAX_SOURCE_CHARS {
                continue;
            }
            variants
                .phrases
                .entry(source_len)
                .or_default()
                .insert(source.to_string(), target.to_string());
            variants.phrase_count += 1;
        }
        variants.lengths = variants.phrases.keys().copied().collect();
        variants
            .lengths
            .sort_unstable_by(|left, right| right.cmp(left));
        variants
    }

    pub fn is_empty(&self) -> bool {
        self.chars.is_empty() && self.phrases.is_empty()
    }

    /// (character rules, phrase rules) — the two numbers in the startup line.
    pub fn rule_counts(&self) -> (usize, usize) {
        (self.chars.len(), self.phrase_count)
    }

    /// Convert one string, left to right, longest match first.
    pub fn to_simplified(&self, input: &str) -> String {
        if self.is_empty() || input.is_empty() {
            return input.to_string();
        }
        let mut out = String::with_capacity(input.len());
        let mut rest = input;
        let mut remaining = input.chars().count();
        while !rest.is_empty() {
            let mut matched = false;
            for &length in &self.lengths {
                if length > remaining {
                    continue;
                }
                let end = char_end(rest, length);
                if let Some(target) = self
                    .phrases
                    .get(&length)
                    .and_then(|table| table.get(&rest[..end]))
                {
                    out.push_str(target);
                    rest = &rest[end..];
                    remaining -= length;
                    matched = true;
                    break;
                }
            }
            if matched {
                continue;
            }
            let character = rest.chars().next().expect("non-empty");
            match self.chars.get(&character) {
                Some(&target) => out.push(target),
                None => out.push(character),
            }
            rest = &rest[character.len_utf8()..];
            remaining -= 1;
        }
        out
    }
}

/// Byte offset just past the first count characters of text.
fn char_end(text: &str, count: usize) -> usize {
    match text.char_indices().nth(count) {
        Some((offset, _)) => offset,
        None => text.len(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A miniature table carrying the cases the reader cares about: two plain
    /// character rules, an identity phrase that must protect 乾隆, and an
    /// 異體字 addendum (衞 → 卫).
    fn sample() -> Variants {
        Variants::parse(
            "# tiny table\n\
             後\t后\n\
             於\t于\n\
             乾\t干\n\
             乾隆\t乾隆\n\
             衞\t卫\n\
             \n\
             白話\t白話\n",
        )
    }

    #[test]
    fn replaces_single_characters() {
        let variants = sample();
        assert_eq!(variants.to_simplified("後"), "后");
        assert_eq!(variants.to_simplified("於"), "于");
        assert_eq!(variants.to_simplified("乾"), "干");
        assert_eq!(variants.to_simplified("衞"), "卫");
    }

    #[test]
    fn identity_phrase_protects_its_word() {
        let variants = sample();
        assert_eq!(variants.to_simplified("乾隆"), "乾隆");
        // Outside the protected word the character rule still applies.
        assert_eq!(variants.to_simplified("乾旱乾隆"), "干旱乾隆");
    }

    #[test]
    fn longest_match_wins_at_each_position() {
        let variants = Variants::parse("乾\t干\n乾隆\t干隆\n乾隆通寶\t乾隆通宝\n");
        assert_eq!(variants.to_simplified("乾隆"), "干隆");
        assert_eq!(variants.to_simplified("乾隆通寶"), "乾隆通宝");
    }

    #[test]
    fn characters_without_a_rule_pass_through() {
        let variants = sample();
        assert_eq!(variants.to_simplified("白話"), "白話");
        assert_eq!(variants.to_simplified("戰國策"), "戰國策");
    }

    #[test]
    fn conversion_is_idempotent() {
        let variants = sample();
        let once = variants.to_simplified("後於乾衞乾隆白話");
        assert_eq!(variants.to_simplified(&once), once);
    }

    #[test]
    fn empty_table_is_a_copy() {
        let variants = Variants::parse("# only comments\n\n");
        assert!(variants.is_empty());
        assert_eq!(variants.rule_counts(), (0, 0));
        assert_eq!(variants.to_simplified("後於乾"), "後於乾");
        assert_eq!(variants.to_simplified(""), "");
    }

    #[test]
    fn rule_counts_separate_characters_from_phrases() {
        assert_eq!(sample().rule_counts(), (4, 2));
    }

    #[test]
    fn malformed_lines_are_skipped_not_fatal() {
        let variants = Variants::parse("no tab here\n後\t后\n\t\n source\ttarget\n");
        assert_eq!(variants.rule_counts(), (1, 1));
        assert_eq!(variants.to_simplified("後"), "后");
    }

    #[test]
    fn load_reads_a_file_and_reports_io_errors() {
        let path = std::env::temp_dir().join("zgc_t2s_unit.tsv");
        std::fs::write(&path, "後\t后\n").expect("write temp table");
        let variants = Variants::load(&path).expect("load temp table");
        assert_eq!(variants.rule_counts(), (1, 0));
        assert_eq!(variants.to_simplified("後"), "后");
        let _ = std::fs::remove_file(&path);
        assert!(Variants::load(Path::new("/nonexistent/zgc/t2s.tsv")).is_err());
    }
}
